def shipping_fee(subtotal_cents):
    if subtotal_cents < 0:
        raise ValueError("subtotal must be nonnegative")
    return 0 if subtotal_cents >= 5000 else 500

import unittest
from shipping import shipping_fee


class ShippingTests(unittest.TestCase):
    def test_threshold(self):
        for subtotal, fee in [(0, 500), (4999, 500), (5000, 0), (5001, 0)]:
            with self.subTest(subtotal=subtotal):
                self.assertEqual(shipping_fee(subtotal), fee)

    def test_negative_subtotal(self):
        with self.assertRaises(ValueError):
            shipping_fee(-1)
